package com.bank.cost;

import java.util.*;
import java.util.logging.*;

public class SummingDemo {
    private static final Logger log = Logger.getLogger("Cost");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000.0),
            new Employee("Amit", "IT", 800000.0),
            new Employee("Priya", "Sales", 250000.0),
            new Employee("Neha", "Sales", 600000.0));
        CostService service = new CostService();

        Map<String, Double> totals = service.totalSalaryByDepartment(staff);
        log.info(() -> "Total salary per department: " + totals);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
        this.name = name; this.department = department; this.salary = salary;
    }
    String getDepartment() { return department; }
    double getSalary() { return salary; }
}

// ─── Would be in service/CostService.java ───
class CostService {
    Map<String, Double> totalSalaryByDepartment(List<Employee> staff) {
        return staff.stream()
            .collect(java.util.stream.Collectors.groupingBy(
                Employee::getDepartment,                              // classifier
                java.util.stream.Collectors.summingDouble(Employee::getSalary))); // sum per group
    }
}
